import com.github.javaparser.JavaParser;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.expr.MethodCallExpr;
import com.github.javaparser.resolution.declarations.ResolvedMethodDeclaration;
import com.github.javaparser.resolution.model.SymbolReference;
import com.github.javaparser.symbolsolver.javaparsermodel.JavaParserFacade;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;

public class Repro {
    public static void main(String[] args) {
        String code = "public class MyExample {\n" +
                "  public static void main(String[] args) {\n" +
                "    \"Hello single %s!\".formatted(\"world\");\n" +
                "    \"\"\"\n" +
                "        Hello multiple %s!\n" +
                "        \"\"\".formatted(\"world\");\n" +
                "  }\n" +
                "}\n";
        ReflectionTypeSolver solver = new ReflectionTypeSolver(false);
        CompilationUnit cu = new JavaParser().parse(code).getResult().get();
        for (MethodCallExpr n : cu.findAll(MethodCallExpr.class)) {
            try {
                SymbolReference<ResolvedMethodDeclaration> solved = JavaParserFacade.get(solver).solve(n);
                System.out.println("Could solve: " + n.getName() + " as " + solved.getCorrespondingDeclaration().getQualifiedSignature());
            } catch (Exception e) {
                System.err.println("Could not solve: " + n.getName() + " -> " + e);
            }
        }
    }
}
EOF
